const ComponentName: React.FC<PainScaleAnimationProps> = ({
  backgroundColor = "#0b132b",
  transparentBackground = false,
  durationInSeconds = 12,
  titleText = "PAIN SCALE",
  titleColorWhite = "#ffffff",
  titleColorRed = "#ff4d4d",
  highlightScale = 1.35,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = durationInSeconds * fps;
  const activeBgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Title Animation (spring bounce on entrance)
  const titleSpring = spring({
    frame,
    fps,
    config: { damping: 12 },
  });

  // Calculate the path progression sweep
  const sweepStartFrame = 15;
  const sweepDuration = totalFrames - 45; // Leave some idle time at the end
  
  // Normalized sweep progress (0 to 10) representing our scale active pointer
  const painIndexProgress = interpolate(
    frame,
    [sweepStartFrame, sweepStartFrame + sweepDuration],
    [0, 10],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Layout-based sizing
  const timelineWidth = width * 0.88;
  const startX = (width - timelineWidth) / 2;
  const nodeSpacing = timelineWidth / 10;
  const centerY = height * 0.58;

  return (
    <AbsoluteFill style={{ backgroundColor: activeBgColor, overflow: "hidden" }}>
      {/* Dynamic Grid Background for deep clinical/tech feel */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          backgroundImage: `
            radial-gradient(circle at 50% 50%, rgba(255,255,255,0.02) 1px, transparent 1px),
            linear-gradient(to right, rgba(255,255,255,0.01) 1px, transparent 1px),
            linear-gradient(to bottom, rgba(255,255,255,0.01) 1px, transparent 1px)
          `,
          backgroundSize: "60px 60px, 40px 40px, 40px 40px",
          opacity: 0.8,
        }}
      />

      {/* Header Panel */}
      <div
        style={{
          position: "absolute",
          top: height * 0.08,
          width: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          transform: `translateY(${interpolate(titleSpring, [0, 1], [-80, 0])}px)`,
          opacity: titleSpring,
          transition: "none",
        }}
      >
        <h1
          style={{
            fontFamily: titleFontFamily,
            fontSize: `${Math.min(width, height) * 0.12}px`,
            margin: 0,
            padding: 0,
            textTransform: "uppercase",
            letterSpacing: "4px",
            lineHeight: 1,
            display: "flex",
            alignItems: "center",
            gap: "16px",
          }}
        >
          <span style={{ color: titleColorWhite }}>{titleText.split(" ")[0] || "PAIN"}</span>
          <span style={{ color: titleColorRed }}>{titleText.split(" ")[1] || "SCALE"}</span>
        </h1>
        <p
          style={{
            fontFamily: bodyFontFamily,
            fontSize: "18px",
            color: "rgba(255, 255, 255, 0.4)",
            margin: "8px 0 0 0",
            letterSpacing: "8px",
            textTransform: "uppercase",
          }}
        >
          Diagnostic Intensity Evaluation
        </p>
      </div>

      {/* Main Track & Interactive Chart Area */}
      <div style={{ position: "absolute", width: "100%", height: "100%", pointerEvents: "none" }}>
        
        {/* Background track line */}
        <div
          style={{
            position: "absolute",
            left: startX,
            top: centerY - 4,
            width: timelineWidth,
            height: 8,
            backgroundColor: "rgba(255, 255, 255, 0.1)",
            borderRadius: 4,
          }}
        />

        {/* Dynamic growing progress bar highlighting current pain level */}
        <div
          style={{
            position: "absolute",
            left: startX,
            top: centerY - 6,
            width: Math.min(painIndexProgress * nodeSpacing, timelineWidth),
            height: 12,
            backgroundImage: "linear-gradient(90deg, #4CAF50 0%, #FFEB3B 35%, #FF5722 70%, #880E4F 100%)",
            backgroundSize: `${timelineWidth}px 12px`,
            borderRadius: 6,
            boxShadow: "0 0 16px rgba(255, 87, 34, 0.4)",
            transition: "none",
          }}
        />

        {/* Render interactive steps, connections, and status cards */}
        {painData.map((item) => {
          const nodeX = startX + item.num * nodeSpacing;
          const isActive = painIndexProgress >= item.num;
          
          // Calculate individual scale boost and emphasis when pointer sweeps over it
          const distanceToPointer = Math.abs(painIndexProgress - item.num);
          const activeScale = interpolate(
            distanceToPointer,
            [0, 0.5, 1.2],
            [highlightScale, 1.1, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          const activeOpacity = interpolate(
            distanceToPointer,
            [0, 1.5],
            [1, 0.45],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Standard staggered entrance animation for nodes
          const nodeEntranceSpring = spring({
            frame: frame - (item.num * 2.5),
            fps,
            config: { stiffness: 150, damping: 12 },
          });

          return (
            <React.Fragment key={item.num}>
              {/* Vertical Tick Divider Lines */}
              {item.num % 2 === 0 && (
                <div
                  style={{
                    position: "absolute",
                    left: nodeX,
                    top: centerY + 90,
                    width: 2,
                    height: 50,
                    backgroundColor: isActive ? item.color : "rgba(255,255,255,0.1)",
                    opacity: nodeEntranceSpring * 0.7,
                    transition: "none",
                  }}
                />
              )}

              {/* Emoji Representation */}
              <div
                style={{
                  position: "absolute",
                  left: nodeX - 35,
                  top: centerY - 140,
                  width: 70,
                  height: 70,
                  transform: `scale(${nodeEntranceSpring * activeScale})`,
                  opacity: nodeEntranceSpring * activeOpacity,
                  filter: isActive ? `drop-shadow(0 0 8px ${item.color}55)` : "none",
                  transition: "none",
                }}
              >
                {item.emojiSvg(isActive ? item.color : "rgba(255, 255, 255, 0.25)")}
              </div>

              {/* Number Node Button */}
              <div
                style={{
                  position: "absolute",
                  left: nodeX - 25,
                  top: centerY - 25,
                  width: 50,
                  height: 50,
                  borderRadius: "50%",
                  backgroundColor: isActive ? item.color : "rgba(20, 30, 55, 0.9)",
                  border: `3px solid ${isActive ? "#ffffff" : "rgba(255,255,255,0.15)"}`,
                  boxShadow: isActive ? `0 0 20px ${item.color}` : "none",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  transform: `scale(${nodeEntranceSpring * activeScale})`,
                  transition: "none",
                }}
              >
                <span
                  style={{
                    fontFamily: titleFontFamily,
                    fontSize: "26px",
                    fontWeight: "bold",
                    color: isActive ? "#ffffff" : "rgba(255,255,255,0.4)",
                    transition: "none",
                  }}
                >
                  {item.label}
                </span>
              </div>
            </React.Fragment>
          );
        })}

        {/* Group Section Labels aligning underneath */}
        <div
          style={{
            position: "absolute",
            left: startX,
            top: centerY + 160,
            width: timelineWidth,
            display: "flex",
            justifyContent: "space-between",
            fontFamily: bodyFontFamily,
            fontWeight: 800,
            fontSize: "14px",
            letterSpacing: "1px",
            textTransform: "uppercase",
          }}
        >
          <div style={{ color: painIndexProgress >= 0 ? "#4CAF50" : "rgba(255,255,255,0.25)", transition: "none", width: nodeSpacing * 2, textAlign: "left" }}>
            No Pain
          </div>
          <div style={{ color: painIndexProgress >= 2 ? "#CDDC39" : "rgba(255,255,255,0.25)", transition: "none", width: nodeSpacing * 2, textAlign: "center" }}>
            Mild Pain
          </div>
          <div style={{ color: painIndexProgress >= 4 ? "#FF9800" : "rgba(255,255,255,0.25)", transition: "none", width: nodeSpacing * 2, textAlign: "center" }}>
            Moderate
          </div>
          <div style={{ color: painIndexProgress >= 6 ? "#FF5722" : "rgba(255,255,255,0.25)", transition: "none", width: nodeSpacing * 2, textAlign: "center" }}>
            Severe
          </div>
          <div style={{ color: painIndexProgress >= 9 ? "#C2185B" : "rgba(255,255,255,0.25)", transition: "none", width: nodeSpacing * 2, textAlign: "right" }}>
            Worst Possible
          </div>
        </div>
      </div>

      {/* Floating Status Card Overlay showcasing active details */}
      {(() => {
        const roundedProgress = Math.min(Math.round(painIndexProgress), 10);
        const activeData = painData[roundedProgress];
        const entrance = spring({
          frame: frame - sweepStartFrame,
          fps,
          config: { damping: 15 },
        });

        return (
          <div
            style={{
              position: "absolute",
              bottom: height * 0.08,
              left: "50%",
              transform: `translateX(-50%) scale(${entrance})`,
              opacity: entrance,
              backgroundColor: "rgba(10, 20, 40, 0.85)",
              border: `2px solid ${activeData.color}`,
              boxShadow: `0 8px 32px rgba(0,0,0,0.5), inset 0 0 12px ${activeData.color}22`,
              padding: "16px 32px",
              borderRadius: "16px",
              backdropFilter: "blur(12px)",
              display: "flex",
              alignItems: "center",
              gap: "24px",
              minWidth: "400px",
              justifyContent: "space-between",
              transition: "none",
            }}
          >
            <div style={{ display: "flex", flexDirection: "column" }}>
              <span style={{ fontFamily: bodyFontFamily, fontSize: "12px", color: "rgba(255,255,255,0.4)", textTransform: "uppercase", letterSpacing: "2px" }}>
                Active Intensity
              </span>
              <span style={{ fontFamily: titleFontFamily, fontSize: "42px", color: activeData.color, lineHeight: 1, letterSpacing: "1px", textTransform: "uppercase", transition: "color 0.15s ease" }}>
                {activeData.category}
              </span>
            </div>
            <div
              style={{
                width: "64px",
                height: "64px",
                borderRadius: "12px",
                backgroundColor: activeData.color,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                boxShadow: `0 0 15px ${activeData.color}55`,
                transition: "background-color 0.15s ease",
              }}
            >
              <span style={{ fontFamily: titleFontFamily, fontSize: "36px", fontWeight: "bold", color: "#ffffff" }}>
                {activeData.num}
              </span>
            </div>
          </div>
        );
      })()}
    </AbsoluteFill>
  );
};

export default ComponentName;